/*
 * Links into the public documentation site (docs.agripulse.cloud).
 *
 * The pages are generated by `docs/website/build.py` in the websites repo, so
 * the file names below are a contract with that script. Keep them here rather
 * than inline in components: a renamed page then breaks in one place instead
 * of five, and the base URL stays overridable per environment.
 *
 * The site has English pages only today, so these links do not vary by
 * locale. When Arabic pages land, add the suffix here.
 */
const DEFAULT_DOCS_BASE = "https://docs.agripulse.cloud";

const configured = import.meta.env.VITE_DOCS_BASE_URL as string | undefined;

export const DOCS_BASE_URL = (configured ?? DEFAULT_DOCS_BASE).replace(/\/+$/, "");

export const DOCS_PAGES = {
  home: "index.html",
  concepts: "concepts.html",
  knowledgeBase: "kb.html",
  support: "support.html",
  guideCreateFarm: "guide-create-a-farm.html",
  guideAddBlocks: "guide-add-the-blocks.html",
  guideGridCellSize: "guide-set-the-grid-cell-size.html",
  guideImageryWeather: "guide-turn-on-imagery-and-weather.html",
  guideAttachPeople: "guide-attach-the-people.html",
  guideCheckArrived: "guide-check-what-arrived.html",
  processMapTheFarm: "process-map-the-farm.html",
  processPlanTheSeason: "process-plan-the-season.html",
  processConnectTheData: "process-connect-the-data.html",
  processReadTheField: "process-read-the-field.html",
  processAuthorTheAgronomy: "process-author-the-agronomy.html",
  processRunTheFieldTeam: "process-run-the-field-team.html",
  processCloseTheLoop: "process-close-the-loop.html",
  processOperateThePlatform: "process-operate-the-platform.html",
} as const;

export type DocsPage = keyof typeof DOCS_PAGES;

export function docsUrl(page: DocsPage): string {
  return `${DOCS_BASE_URL}/${DOCS_PAGES[page]}`;
}
